package com.qubole.rubix.bookkeeper;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.SynchronousQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Regression test for the ThreadPoolExecutor rejection bug in LocalDataTransferServer.
 *
 * The PR replaced Executors.newCachedThreadPool() with:
 *   new ThreadPoolExecutor(0, getLocalTransferServerMaxThreads(conf), 60L, SECONDS,
 *       new SynchronousQueue<>(), threadsNamed("lds-worker-%s"))
 *
 * SynchronousQueue has zero capacity — offer() only succeeds when an idle thread is
 * immediately available to take the task. With bounded maxThreads (default 4096), when
 * all threads are busy, new tasks are REJECTED with RejectedExecutionException, causing
 * dropped client connections. The old newCachedThreadPool (Integer.MAX_VALUE max) never
 * rejected.
 *
 * This test can be run standalone (no framework needed):
 *   java com.qubole.rubix.bookkeeper.ThreadPoolRejectionBugTest
 */
public class ThreadPoolRejectionBugTest
{
  /**
   * Demonstrates that a bounded ThreadPoolExecutor with SynchronousQueue DOES reject
   * tasks when all worker threads are occupied — which is the bug introduced by the PR.
   * 
   * This test uses a small maxThreads (4) to trigger the bug quickly in the test.
   * In production, maxThreads defaults to 4096, but the behavior is the same.
   * 
   * Returns false when the bug is present (task rejected), true when fixed.
   */
  public boolean testBoundedThreadPoolWithSynchronousQueueRejectsUnderLoad() throws Exception
  {
    int maxThreads = 4;

    // This is the exact pattern introduced by the PR in LocalDataTransferServer.run()
    ExecutorService pool = new ThreadPoolExecutor(
            0, maxThreads,
            60L, TimeUnit.SECONDS,
            new SynchronousQueue<>(),
            r -> new Thread(r, "test-lds-worker"));

    CountDownLatch blockLatch = new CountDownLatch(1);
    CountDownLatch workersStarted = new CountDownLatch(maxThreads);

    // Fill the pool with blocking tasks
    for (int i = 0; i < maxThreads; i++) {
      pool.execute(() -> {
        workersStarted.countDown();
        try {
          blockLatch.await(); // block until released
        } catch (InterruptedException e) {
          Thread.currentThread().interrupt();
        }
      });
    }

    // Wait for all workers to be blocked
    if (!workersStarted.await(10, TimeUnit.SECONDS)) {
      throw new AssertionError("Workers should have started and blocked");
    }

    // Now try to submit one more task
    AtomicBoolean rejected = new AtomicBoolean(false);
    try {
      pool.execute(() -> {
        // This should have been accepted without rejection
      });
    } catch (RejectedExecutionException e) {
      rejected.set(true);
    }

    // Clean up
    blockLatch.countDown();
    pool.shutdownNow();
    pool.awaitTermination(10, TimeUnit.SECONDS);

    // The bug: with SynchronousQueue + bounded maxThreads, the task IS rejected
    // PASS (return true) if NOT rejected; FAIL (return false) if rejected
    if (rejected.get()) {
      System.err.println("FAIL: ThreadPoolExecutor with SynchronousQueue and bounded maxThreads=" + maxThreads +
          " REJECTED a task when all workers were busy. This causes dropped client " +
          "connections in LocalDataTransferServer. The old Executors.newCachedThreadPool() " +
          "never rejected because it had Integer.MAX_VALUE maxThreads.");
      return false;
    }
    return true;
  }

  /**
   * Confirms that Executors.newCachedThreadPool() (the old code) does NOT reject
   * under the same conditions. This shows the old behavior was correct.
   */
  public boolean testCachedThreadPoolDoesNotRejectUnderLoad() throws Exception
  {
    // The old code: Executors.newCachedThreadPool() = unbounded max threads
    ExecutorService pool = Executors.newCachedThreadPool(
        r -> new Thread(r, "test-old-worker"));

    int numWorkers = 20;
    CountDownLatch blockLatch = new CountDownLatch(1);
    CountDownLatch workersStarted = new CountDownLatch(numWorkers);

    // Fill with blocking tasks
    for (int i = 0; i < numWorkers; i++) {
      pool.execute(() -> {
        workersStarted.countDown();
        try {
          blockLatch.await();
        } catch (InterruptedException e) {
          Thread.currentThread().interrupt();
        }
      });
    }

    if (!workersStarted.await(10, TimeUnit.SECONDS)) {
      throw new AssertionError("Workers should have started and blocked");
    }

    // Submit one more task
    AtomicBoolean rejected = new AtomicBoolean(false);
    try {
      pool.execute(() -> { });
    } catch (RejectedExecutionException e) {
      rejected.set(true);
    }

    blockLatch.countDown();
    pool.shutdownNow();
    pool.awaitTermination(10, TimeUnit.SECONDS);

    if (rejected.get()) {
      System.err.println("FAIL: newCachedThreadPool should not reject tasks under load");
      return false;
    }
    return true;
  }

  public static void main(String[] args) throws Exception
  {
    ThreadPoolRejectionBugTest test = new ThreadPoolRejectionBugTest();
    int failures = 0;

    // Test 1: Bounded pool with SynchronousQueue should NOT reject (this will FAIL - showing the bug)
    System.out.println("Test 1: testBoundedThreadPoolWithSynchronousQueueRejectsUnderLoad");
    if (!test.testBoundedThreadPoolWithSynchronousQueueRejectsUnderLoad()) {
      failures++;
    }

    // Test 2: CachedThreadPool should NOT reject (baseline - should PASS)
    System.out.println("Test 2: testCachedThreadPoolDoesNotRejectUnderLoad");
    if (!test.testCachedThreadPoolDoesNotRejectUnderLoad()) {
      failures++;
    }

    if (failures > 0) {
      System.err.println("\n" + failures + " test(s) FAILED");
      System.exit(1);
    } else {
      System.out.println("All tests PASSED");
      System.exit(0);
    }
  }
}
